document.addEventListener('DOMContentLoaded', () => {
    const newsfeed = document.querySelector('.wf-cpanel-newsfeed');

    if (newsfeed) {
        newsfeed.classList.add('loading');

        // Get feed
        fetch("index.php?option=com_jce&task=cpanel.feed")
            .then(response => response.json())
            .then(data => {
                const newsfeed = document.querySelector('.wf-cpanel-newsfeed');

                newsfeed.classList.remove('loading');
                newsfeed.innerHTML = '';

                if (!data || !data.feeds) {
                    return;
                }

                data.feeds.forEach(feed => {
                    const html = `<li><a href="${feed.link}" target="_blank" title="${feed.title}">${feed.title}</a></li>`;
                    newsfeed.insertAdjacentHTML('beforeend', html);
                });
            });
    }

    const newsfeedEnable = document.getElementById('newsfeed_enable');

    if (newsfeedEnable) {
        // Open config/preferences dialog
        newsfeedEnable.addEventListener('click', (e) => {
            e.preventDefault();
            document.getElementById('toolbar-options').click();
        });
    }
});  